example.code:
WITH RECURSIVE f(n, fact) AS (
    SELECT 1, 1::numeric
    UNION ALL
    SELECT n + 1, fact * (n + 1) FROM f WHERE n < 6
)
SELECT n, fact AS factorial FROM f ORDER BY n;

